import React, { useState } from 'react';
import Cropper from 'react-easy-crop';
import { I18n } from '@fiverr-private/i18n-react';
import { Box } from '@fiverr-private/theme';
import { Text } from '@fiverr-private/typography';
import { DEFAULT_CROP, DEFAULT_ASPECT_RATIO, DEFAULT_SHAPE } from './constants';
import type { ImageCropProps } from './types';
import Range from './Range';

const ImageCrop = ({
  aspectRatio = DEFAULT_ASPECT_RATIO,
  shape = DEFAULT_SHAPE,
  src,
  crop: _crop = DEFAULT_CROP,
  onChange,
  width = '100%',
  height = '220px',
  dataTrackTag = 'image_crop',
  dataTrackValue,
}: ImageCropProps) => {
  const [crop, setCrop] = useState(_crop);
  const [cropSize, setCropSize] = useState({ width: 0, height: 0 });
  const [zoom, setZoom] = useState(1);

  return (
    <>
      <Box
        dataTrackTag={dataTrackTag}
        dataTrackValue={dataTrackValue}
        width={width}
        height={height}
        backgroundColor="black"
        position="relative"
        marginBottom="3"
        flex={1}
      >
        <Cropper
          image={src}
          crop={crop}
          cropSize={cropSize}
          cropShape={shape}
          zoom={zoom}
          onCropChange={setCrop}
          onCropComplete={onChange}
          onZoomChange={setZoom}
          onMediaLoaded={({ width, height }) => {
            if (shape === 'round') {
              const diameter = Math.min(width, height);
              setCropSize({
                width: diameter,
                height: diameter,
              });
            } else {
              const cropHeight = width / aspectRatio;
              setCropSize({
                width,
                height: Math.min(cropHeight, height),
              });
            }
          }}
        />
      </Box>
      <Text marginBottom="8" textAlign="center" width="100%" color="bodySecondary">
        <I18n k="media.imageCrop.dragImage" />
      </Text>
      <Range zoom={zoom} onChange={setZoom} />
    </>
  );
};

ImageCrop.displayName = 'ImageCrop';

export default ImageCrop;
