import React, { useMemo, useEffect } from 'react';
import { Box } from '@fiverr-private/theme';
import { Typography } from '@fiverr-private/typography';
import type { RangeProps } from './types';
import { MIN_ZOOM, MAX_ZOOM, ZOOM_STEP } from './constants';
import { zoomRange } from './styles.ve.css';

const Range = ({ zoom, onChange }: RangeProps) => {
  const zoomPercentage = useMemo(() => Math.floor(((zoom - MIN_ZOOM) / (MAX_ZOOM - MIN_ZOOM)) * 100), [zoom]);

  useEffect(() => {
    document.documentElement.style.setProperty('--crop-zoom', `${zoomPercentage}%`);
  }, [zoomPercentage]);

  return (
    <Box display="flex" direction="column">
      <Box
        as="label"
        htmlFor="range"
        display="flex"
        justifyContent="spaceBetween"
        color="grey_1100"
        lineHeight="b_md"
        fontSize="b_md"
        fontWeight="semibold"
        marginBottom="4"
        dataTrackTag="image_crop_range"
        dataTrackValue={String(zoom)}
      >
        <Typography as="span">Zoom</Typography>
        <Typography as="span">{zoomPercentage}%</Typography>
      </Box>
      <Box
        as="input"
        id="range"
        type="range"
        value={zoom}
        min={MIN_ZOOM}
        max={MAX_ZOOM}
        step={ZOOM_STEP}
        height="4px"
        backgroundColor="grey_900"
        borderRadius="md"
        width="100%"
        aria-labelledby="Zoom"
        appearance="none"
        onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
          onChange(Number(e.target.value));
        }}
        className={zoomRange}
      />
    </Box>
  );
};

Range.displayName = 'Range';

export default Range;
